void phone_page_update_language(lang_type_t lang)
{
    aic_set_language(lang);
    phone_page_update_current_language();
}

void phone_page_update_current_language(void)
{
    phone_page_t *scr = phone_page_get(&ui_manager);
    /* 投屏页未构建时（语言在设置页被切换）安全返回，避免解引用 NULL */
    if (!scr->obj || !scr->qr_tips)
        return;

    lv_obj_set_style_text_font(scr->qr_tips, aic_get_multi_lang_font(16), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_label_set_text(scr->qr_tips, aic_get_translation(qr_tips));
}

